#include <charconv>
#include <iostream>
#include <string>
#include <system_error>

void tryParse(const std::string& text)
{
    int value{};
    auto [ptr, ec]{std::from_chars(text.data(), text.data() + text.size(), value)};
    std::cout << text << " -> " << value << '\n';
}

int main()
{
    for (std::string t : {"42", "42abc", "abc", "99999999999"}) tryParse(t);
}
